-- ===== U3/U4 vocab 覆盖灌库(volume='9')。分步跑,每步贴回 count。=====


-- ========================= U3 (39 词) =========================
-- [step0] 灌前 count(预期 31)
SELECT 'U3 灌前' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U3';

-- [step1] DELETE 旧词(键对准旧骨架实际存储:grade=9 volume='9' unit='U3')
DELETE FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U3';
-- [step1 验证] 预期 0
SELECT 'U3 DELETE后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U3';

-- [step2] INSERT 官方 39 词(volume='9';含 WHERE NOT EXISTS 防重)
-- [step2 验证] 预期 39
SELECT 'U3 INSERT后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U3';

-- ========================= U4 (39 词) =========================
-- [step0] 灌前 count(预期 29)
SELECT 'U4 灌前' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U4';

-- [step1] DELETE 旧词(键对准旧骨架实际存储:grade=9 volume='9' unit='U4')
DELETE FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U4';
-- [step1 验证] 预期 0
SELECT 'U4 DELETE后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U4';

-- [step2] INSERT 官方 39 词(volume='9';含 WHERE NOT EXISTS 防重)
-- [step2 验证] 预期 39
SELECT 'U4 INSERT后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U4';

-- ========================= 末尾查重(预期 0 行) =========================
SELECT word, unit, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit IN ('U3','U4') GROUP BY word, unit HAVING count(*) > 1;